import java.nio.file.*;
import java.util.*;

/** Regenerates portfolio examples directly from the simulator, without hand-entered metrics. */
public class GenerateReport {
    public static void main(String[] args) throws Exception {
        Process[] input = scheduling_algorithms.load(Path.of("workloads/comparison.txt"));
        List<Scheduler.Result> results = new ArrayList<>();
        for (Scheduler.Algorithm alg : new Scheduler.Algorithm[]{Scheduler.Algorithm.FCFS,Scheduler.Algorithm.SJF,Scheduler.Algorithm.SRTF}) results.add(Scheduler.schedule(input,alg,0));
        for (int q : new int[]{1,2,5,10}) results.add(Scheduler.schedule(input,Scheduler.Algorithm.RR,q));
        StringBuilder md = new StringBuilder("# Executed comparison\n\nGenerated by `GenerateReport` from `workloads/comparison.txt`. All times are simulated milliseconds.\n\n");
        md.append("| PID (input order) | Arrival | Burst |\n|---|---:|---:|\n");
        for (Process p : input) md.append("| ").append(p.pid).append(" | ").append(p.arrivalTime).append(" | ").append(p.burstTime).append(" |\n");
        md.append("\n![Executed Gantt charts](gantt.svg)\n\n| Algorithm | Average waiting | Average turnaround |\n|---|---:|---:|\n");
        for (Scheduler.Result r : results) md.append(String.format(Locale.ROOT,"| %s | %.3f | %.3f |%n",r.algorithm(),r.averageWaiting(),r.averageTurnaround()));
        md.append("\nThese are workload results, not wall-clock benchmarks or a general ranking of algorithms. SRTF ties use input order: C precedes B in this file and preempts B when both have one unit remaining at time 2.\n");
        String[] colors = {"#2563eb","#d97706","#0f766e","#9333ea"};
        Map<String,String> palette = new HashMap<>();
        for (int i=0;i<input.length;i++) palette.put(input[i].pid,colors[i % colors.length]);
        int finish = results.get(0).slices().get(results.get(0).slices().size()-1).end();
        int left=200, width=750, height=110+results.size()*76;
        StringBuilder svg = new StringBuilder("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"1000\" height=\""+height+"\" viewBox=\"0 0 1000 "+height+"\" role=\"img\" aria-labelledby=\"title desc\">\n<title id=\"title\">CPU scheduling comparison</title><desc id=\"desc\">Seven schedules computed from the same workload. Gray intervals show idle CPU time. Horizontal axis is simulated milliseconds.</desc>\n<rect width=\"100%\" height=\"100%\" fill=\"#ffffff\"/><g font-family=\"Arial, sans-serif\" font-size=\"14\">\n<text x=\"24\" y=\"30\" font-size=\"22\" font-weight=\"bold\">CPU scheduling: same workload, different policies</text>\n<text x=\"24\" y=\"55\" fill=\"#475569\">Arrival/burst: A 0/5, C 2/1, B 1/2, D 12/3. Gray = IDLE. Time in ms.</text>\n");
        int row=0;
        for (Scheduler.Result r : results) {
            int y=85+row++*76;
            svg.append("<text x=\"24\" y=\"").append(y+25).append("\" fill=\"#0f172a\">").append(r.algorithm()).append("</text>\n");
            md.append("\n## ").append(r.algorithm()).append("\n\n```text\n0");
            for (Scheduler.Slice s : r.slices()) {
                String pid=s.pid()==null?"IDLE":s.pid();
                md.append(" | ").append(pid).append(" | ").append(s.end());
                int x=left+s.start()*width/finish, w=(s.end()-s.start())*width/finish;
                svg.append("<rect x=\"").append(x).append("\" y=\"").append(y).append("\" width=\"").append(w).append("\" height=\"38\" fill=\"").append(s.pid()==null?"#64748b":palette.get(s.pid())).append("\" stroke=\"white\"/>\n<text x=\"").append(x+w/2).append("\" y=\"").append(y+24).append("\" text-anchor=\"middle\" fill=\"white\">").append(pid).append("</text>\n");
            }
            for(int t=0;t<=finish;t++) svg.append("<text x=\"").append(left+t*width/finish).append("\" y=\"").append(y+56).append("\" text-anchor=\"middle\" fill=\"#475569\" font-size=\"12\">").append(t).append("</text>\n");
            md.append("\n```\n\n| PID | First start | Completion | Waiting | Turnaround |\n|---|---:|---:|---:|---:|\n");
            for (Process p : r.processes()) md.append(String.format(Locale.ROOT,"| %s | %d | %d | %d | %d |%n",p.pid,p.startTime,p.completionTime,p.waitingTime,p.turnTime));
        }
        svg.append("</g></svg>\n");
        Files.createDirectories(Path.of("docs"));
        Files.writeString(Path.of("docs/example.md"),md);
        Files.writeString(Path.of("docs/gantt.svg"),svg);
        System.out.println("Generated docs/example.md and docs/gantt.svg from actual scheduling results");
    }
}
